package com.justjava.humanresource.employeeexit.service; import com.justjava.humanresource.employeeexit.dto.*; import com.justjava.humanresource.employeeexit.enums.*; import com.justjava.humanresource.employeeexit.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*; import java.util.stream.Collectors;
@Service @RequiredArgsConstructor public class EmployeeExitReportService {private final EmployeeExitCaseRepository exits;private final ExitSettlementRepository settlements;private final ExitAssetReturnRepository assets;
 @Transactional(readOnly=true)public ExitDashboardSummary summary(){return summary(new ExitReportFilter());}
 @Transactional(readOnly=true)public ExitDashboardSummary summary(ExitReportFilter filter){var all=exits.findAllByOrderByCreatedAtDesc().stream().filter(x->matches(x,filter)).toList();var byStatus=all.stream().collect(Collectors.groupingBy(x->x.getStatus().name(),LinkedHashMap::new,Collectors.counting()));var byType=all.stream().collect(Collectors.groupingBy(x->x.getExitType().name(),LinkedHashMap::new,Collectors.counting()));long active=all.stream().filter(x->!EnumSet.of(ExitStatus.COMPLETED,ExitStatus.REJECTED,ExitStatus.CANCELLED).contains(x.getStatus())).count();BigDecimal liability=all.stream().map(x->settlements.findFirstByExitCaseIdOrderBySettlementVersionDesc(x.getId()).orElse(null)).filter(Objects::nonNull).filter(s->EnumSet.of(SettlementStatus.APPROVED,SettlementStatus.POSTED,SettlementStatus.PAYMENT_PENDING).contains(s.getStatus())).map(s->s.getNetSettlement().max(BigDecimal.ZERO)).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal recovery=all.stream().flatMap(x->assets.findByExitCaseIdOrderByAssetName(x.getId()).stream()).filter(a->a.getRecoveryAmount()!=null).map(a->a.getRecoveryAmount()).reduce(BigDecimal.ZERO,BigDecimal::add);return new ExitDashboardSummary(all.size(),active,byStatus.getOrDefault(ExitStatus.CLEARANCE_IN_PROGRESS.name(),0L),liability,recovery,byStatus,byType);}
 private boolean matches(com.justjava.humanresource.employeeexit.entity.EmployeeExitCase x,ExitReportFilter f){if(f==null)return true;if(f.getStatus()!=null&&x.getStatus()!=f.getStatus())return false;if(f.getExitType()!=null&&x.getExitType()!=f.getExitType())return false;if(f.getFrom()!=null&&x.getRequestDate()!=null&&x.getRequestDate().isBefore(f.getFrom()))return false;if(f.getTo()!=null&&x.getRequestDate()!=null&&x.getRequestDate().isAfter(f.getTo()))return false;return true;}}
